languages.solution:
const values = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const [n, target] = values;
let bestId = -1;
let bestScore = -Infinity;
for (let index = 2; index < 2 + n * 3; index += 3) {
  const [doc, tenant, score] = values.slice(index, index + 3);
  if (tenant === target && (score > bestScore || (score === bestScore && doc < bestId))) {
    bestId = doc;
    bestScore = score;
  }
}
console.log(bestId);

